export const BODY: string = "\n<p>SVG اور PNG دو بالکل مختلف تصویریں ہیں۔ SVG ویکٹر ہے، جو حساب سے بنتا ہے۔ PNG ریسٹر ہے، جو پکسلز سے بنتا ہے۔ یہ فرق ہر چیز طے کرتا ہے۔</p>\n<p>ویکٹر کو جتنا بڑا کریں، وہ اتنا ہی تیز رہتا ہے۔ ریسٹر کو بڑا کرنے پر وہ دھندلا ہو جاتا ہے۔ اس لیے لوگو کے لیے SVG اور تصویر کے لیے PNG بہتر ہے۔</p>\n<p>یہ مضمون دونوں کا موازنہ کرتا ہے: اسکیل، فائل سائز، شفافیت، ایڈیٹنگ اور براؤزر سپورٹ۔ آخر میں ایک واضح فیصلہ ہے کہ کب کون سا استعمال کریں۔</p>\n<h2 id=\"what-is-vector\">ویکٹر تصویر کیا ہے؟</h2>\n<p>ویکٹر تصویر لکیروں، شکلوں اور رنگوں کے حساب سے بنتی ہے، پکسلز سے نہیں۔ اس حساب کو ہر سائز میں دوبارہ چلایا جا سکتا ہے۔</p>\n<p>ویکٹر کی سب سے بڑی خوبی یہ ہے کہ وہ ہر سائز میں تیز رہتا ہے۔ چھوٹا آئیکن اور بڑا بینر، دونوں ایک ہی SVG سے بنتے ہیں۔</p>\n<p>ویکٹر لوگو، آئیکن اور سادہ گرافک کے لیے بنایا گیا تھا۔ پیچیدہ تصویر، جیسے فوٹو، ویکٹر میں نہیں بنتی۔</p>\n<h2 id=\"what-is-raster\">ریسٹر تصویر کیا ہے؟</h2>\n<p>ریسٹر تصویر پکسلز کی جالی ہے، جس میں ہر پکسل کا اپنا رنگ ہوتا ہے۔ PNG، JPG اور WebP سب ریسٹر ہیں۔</p>\n<p>ریسٹر تصویر کا سائز طے ہوتا ہے: 1000 پکسلز تصویر میں 1000 پکسلز ہوتے ہیں۔ اسے بڑا کرنے پر پکسلز کھل جاتے ہیں اور تصویر دھندلی ہو جاتی ہے۔</p>\n<p>ریسٹر فوٹو اور پیچیدہ تصویر کے لیے بنایا گیا تھا، کیونکہ فوٹو میں لاکھوں رنگ ہوتے ہیں جو حساب سے نہیں بنتے۔</p>\n<h2 id=\"scaling-compared\">اسکیل کا موازنہ</h2>\n<p>SVG کو 10 گنا بڑا کریں تو بھی وہ تیز رہتا ہے، کیونکہ حساب دوبارہ چلتا ہے۔ PNG کو 10 گنا بڑا کریں تو وہ دھندلا اور پکسل والا ہو جاتا ہے۔</p>\n<p>اسکیل کا فرق لوگو میں سب سے زیادہ نظر آتا ہے۔ SVG لوگو ہر سائز میں تیز ہے، PNG لوگو صرف اس سائز میں تیز ہے جس پر وہ بنا تھا۔</p>\n<p>ریٹینا اسکرین پر فرق اور بھی بڑھ جاتا ہے، کیونکہ وہ زیادہ پکسلز مانگتی ہے۔ SVG وہاں بھی تیز رہتا ہے۔</p>\n<h2 id=\"file-size-compared\">فائل سائز کا موازنہ</h2>\n<p>سادہ لوگو کی SVG چند کلو بائٹ کی ہوتی ہے، جب کہ اسی لوگو کی PNG سینکڑوں کلو بائٹ کی ہو سکتی ہے۔ SVG حساب رکھتا ہے، PNG ہر پکسل رکھتا ہے۔</p>\n<p>پیچیدہ تصویر میں فرق الٹ جاتا ہے: فوٹو کی SVG بہت بڑی ہو جاتی ہے، جب کہ PNG چھوٹا رہتا ہے۔ اس لیے فوٹو ہمیشہ ریسٹر میں رکھیں۔</p>\n<p>فائل سائز کا فیصلہ تصویر کی نوعیت پر منحصر ہے، فارمیٹ پر نہیں۔ سادہ گرافک میں SVG چھوٹا، پیچیدہ تصویر میں PNG چھوٹا۔</p>\n<h2 id=\"transparency-compared\">شفافیت کا موازنہ</h2>\n<p>SVG اور PNG دونوں شفافیت رکھتے ہیں۔ SVG میں شفافیت حساب کا حصہ ہے، PNG میں ہر پکسل کی شفافیت الگ سے لکھی ہوتی ہے۔</p>\n<p>لوگو کے لیے دونوں کام کرتے ہیں۔ فرق یہ ہے کہ SVG شفافیت کے ساتھ بھی ہلکا رہتا ہے، PNG شفافیت کے ساتھ بھاری ہو جاتا ہے۔</p>\n<p>JPG شفافیت نہیں رکھتا، اس لیے شفاف لوگو کے لیے SVG یا PNG چنیں، JPG نہیں۔</p>\n<h2 id=\"editing-compared\">ایڈیٹنگ کا موازنہ</h2>\n<p>SVG کو ایڈٹ کرنا آسان ہے: شکل کا رنگ یا سائز بدلنا ایک لائن کی تبدیلی ہے۔ PNG کو ایڈٹ کرنا مشکل ہے، کیونکہ پکسلز طے ہوتے ہیں۔</p>\n<p>SVG ایڈیٹ کرنے کے لیے ویکٹر ایڈیٹر چاہیے، جیسے Figma یا Illustrator۔ PNG ہر ایڈیٹر میں کھلتا ہے۔</p>\n<p>لوگو کی رنگت بدلنی ہو تو SVG میں سیکنڈوں کا کام ہے، PNG میں گھنٹوں کا۔ اس لیے لوگو ہمیشہ SVG میں رکھیں۔</p>\n<h2 id=\"browser-support\">براؤزر سپورٹ</h2>\n<p>جدید براؤزر SVG اور PNG دونوں کھولتے ہیں۔ SVG ویب میں براہ راست چلتا ہے، PNG بھی۔ فرق پرانے سافٹ ویئر میں آتا ہے۔</p>\n<p>پرانے براؤزر اور پرانا سافٹ ویئر SVG نہیں کھولتے، مگر PNG کھولتے ہیں۔ اس لیے پرانے سسٹم کے لیے PNG نقل رکھیں۔</p>\n<p>ای میل کلائنٹ میں SVG اکثر نہیں کھلتا، PNG ہمیشہ کھلتا ہے۔ ای میل کے لیے PNG چنیں۔</p>\n<h2 id=\"when-to-use-svg\">SVG کب استعمال کریں</h2>\n<p>SVG اس وقت استعمال کریں جب تصویر سادہ ہو: لوگو، آئیکن، چارٹ یا سادہ گرافک۔ وہ ہر سائز میں تیز اور ہلکا رہتا ہے۔</p>\n<p>SVG اس وقت بھی استعمال کریں جب تصویر کو بار بار ایڈٹ کرنا ہو۔ رنگ یا سائز بدلنا SVG میں آسان ہے۔</p>\n<p>ویب کے لیے SVG بہتر ہے، کیونکہ وہ ہلکا ہے اور صفحہ تیز لوڈ ہوتا ہے۔</p>\n<h2 id=\"when-to-use-png\">PNG کب استعمال کریں</h2>\n<p>PNG اس وقت استعمال کریں جب تصویر پیچیدہ ہو: فوٹو، اسکرین شاٹ یا تفصیلی تصویر۔ وہ ہر جگہ کھلتا ہے۔</p>\n<p>PNG اس وقت بھی استعمال کریں جب SVG کہیں نہ کھلے، جیسے ای میل، پرانا سافٹ ویئر یا سوشل میڈیا۔ PNG محفوظ انتخاب ہے۔</p>\n<p>PNG اس وقت بھی استعمال کریں جب تصویر کو ایڈٹ کرنا ہو اور ویکٹر ایڈیٹر دستیاب نہ ہو۔</p>\n<h2 id=\"converting-between-them\">دونوں کے درمیان تبدیلی</h2>\n<p>SVG کو PNG میں بدلنا آسان ہے: ریسٹرائز کریں اور درست اسکیل چنیں۔ PNG کو SVG میں بدلنا مشکل ہے، کیونکہ پکسلز سے حساب واپس نہیں بنتا۔</p>\n<p>PNG سے SVG بنانے والے ٹول صرف اندازہ لگاتے ہیں، اور نتیجہ اصل جیسا نہیں ہوتا۔ اس لیے اصل SVG محفوظ رکھیں۔</p>\n<p>تبدیلی کے لیے <a href=\"/ur/svg-ko-png-mein-convert-karein/\">SVG ٹو PNG</a> استعمال کریں، اور تفصیل <a href=\"/ur/blog/svg-ko-png-rehnumai/\">SVG ٹو PNG گائیڈ</a> میں دیکھیں۔</p>\n<h2 id=\"practical-workflow\">عملی ورک فلو</h2>\n<p>عملی ورک فلو یہ ہے: لوگو اور آئیکن SVG میں بنائیں اور محفوظ رکھیں، اور ضرورت کے وقت PNG نقل بنائیں۔ اصل ہمیشہ SVG رہے۔</p>\n<p>ویب سائٹ پر SVG استعمال کریں، سوشل میڈیا اور ای میل کے لیے PNG بنائیں۔ دونوں ایک ہی اصل سے بنتے ہیں۔</p>\n<p>فوٹو ہمیشہ PNG یا JPG میں رکھیں، SVG میں نہیں۔ فوٹو ویکٹر نہیں بنتی۔</p>\n<h2 id=\"verdict\">حتمی فیصلہ</h2>\n<p>نہ SVG بہتر ہے، نہ PNG — دونوں مختلف کام کے لیے ہیں۔ سادہ گرافک کے لیے SVG، پیچیدہ تصویر کے لیے PNG۔</p>\n<p>اگر صرف ایک فارمیٹ رکھنا ہو تو PNG رکھیں، کیونکہ وہ ہر جگہ کھلتا ہے۔ لیکن لوگو کے لیے SVG بھی رکھیں۔</p>\n<p>بہترین حکمت عملی یہ ہے: اصل SVG میں، نقل PNG میں۔ اس سے ہر جگہ کام چلتا ہے۔</p>\n<h2 id=\"vector-in-animation\">اینیمیشن میں ویکٹر</h2>\n<p>SVG اینیمیشن کے لیے بہترین ہے، کیونکہ اس کی شکلوں کو حرکت دی جا سکتی ہے۔ SVG اینیمیشن ہلکی اور تیز ہوتی ہے۔</p>\n<p>PNG اینیمیشن کے لیے فریم بہ فریم تصویر چاہیے، جو بھاری ہوتی ہے۔ اس لیے اینیمیشن میں SVG چنیں۔</p>\n<p>ویب اینیمیشن، لوڈنگ آئیکن اور انٹرایکٹو گرافک میں SVG استعمال کریں۔</p>\n<h2 id=\"raster-in-photography\">فوٹوگرافی میں ریسٹر</h2>\n<p>فوٹوگرافی میں ریسٹر ہی چلتا ہے، کیونکہ کیمرہ پکسلز بناتا ہے، حساب نہیں۔ فوٹو ہمیشہ ریسٹر میں رہتی ہے۔</p>\n<p>فوٹو کو SVG میں بدلنے کی کوشش نہ کریں۔ نتیجہ بڑا اور خراب ہوتا ہے۔ فوٹو کے لیے PNG یا JPG چنیں۔</p>\n<p>فوٹو ایڈیٹنگ میں بھی ریسٹر ایڈیٹر استعمال ہوتے ہیں، جیسے Photoshop۔ ویکٹر ایڈیٹر فوٹو کے لیے نہیں بنے۔</p>\n<h2 id=\"raster-in-games\">گیمز میں ریسٹر</h2>\n<p>گیمز میں ریسٹر تصویر استعمال ہوتی ہے، کیونکہ گیم انجن پکسلز سے کام کرتا ہے۔ کردار اور پس منظر PNG میں ہوتے ہیں۔</p>\n<p>گیم کے آئیکن اور UI SVG میں ہو سکتے ہیں، مگر کھیل کی تصویر ریسٹر میں رہتی ہے۔</p>\n<p>گیم میں دونوں کا امتزاج چلتا ہے: UI ویکٹر، تصویر ریسٹر۔</p>\n<h2 id=\"hybrid-workflows\">ہائبرڈ ورک فلو</h2>\n<p>ہائبرڈ ورک فلو میں دونوں فارمیٹ ایک ساتھ استعمال ہوتے ہیں۔ لوگو SVG میں، فوٹو PNG میں، اور ہر ایک اپنی جگہ درست ہے۔</p>\n<p>ہائبرڈ ورک فلو میں اصل فائلیں الگ رکھیں: SVG اصل، PNG نقل۔ نقل کو دوبارہ بنانا آسان ہے، اصل کو نہیں۔</p>\n<p>ٹیم میں ہائبرڈ ورک فلو لکھ کر دیں، تاکہ ہر کوئی جانے کہ کب کون سا فارمیٹ استعمال کرنا ہے۔</p>\n<h2 id=\"teaching-vector-raster\">ویکٹر اور ریسٹر سکھانا</h2>\n<p>ویکٹر اور ریسٹر سکھانے کے لیے ایک ہی لوگو دونوں فارمیٹ میں دکھائیں۔ دونوں کو بڑا کر کے فرق دیکھیں: SVG تیز، PNG دھندلا۔</p>\n<p>طلبہ کو بتائیں کہ فوٹو ریسٹر ہے اور لوگو ویکٹر۔ یہ فرق سمجھنا ڈیزائن کی بنیاد ہے۔</p>\n<p>عملی مشق یہ ہے: ایک SVG لوگو بنائیں، اسے PNG میں بدلیں، اور دونوں کو مختلف سائز میں دیکھیں۔ فرق خود نظر آ جائے گا۔ تبدیلی کے مراحل <a href=\"/ur/blog/svg-ko-png-mein-kaise-convert-karein/\">SVG کو PNG میں کیسے بدلیں</a> میں دیکھیں۔</p>\n";

